'use strict';
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(n/100),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let products=[],cart=[];try{cart=JSON.parse(localStorage.getItem('sudsys-basket-v1')||'[]');if(!Array.isArray(cart))cart=[];}catch{cart=[];}
function save(){try{localStorage.setItem('sudsys-basket-v1',JSON.stringify(cart));}catch{}const n=cart.reduce((a,b)=>a+b.qty,0);$('#cart-count').textContent=n;$('#cart-count').hidden=!n;}
function available(v){return !v.tracked||v.continue||v.stock>0}
function cap(v){return v.tracked&&!v.continue?Math.max(0,v.stock):99}
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(title,text){$('#notice-title').textContent=title;$('#notice-text').textContent=text;$('#notice').showModal()}
$('#notice-close').onclick=$('#notice-ok').onclick=()=>$('#notice').close();
$('#account').onclick=()=>modal('Customer accounts','This preview does not include customer sign-in. Account and order-management options will be set up before the shop goes live.');
$('#search-toggle').onclick=()=>{$('#search-panel').hidden=!$('#search-panel').hidden;if(!$('#search-panel').hidden)$('#search').focus()};
$('#search-close').onclick=()=>{$('#search-panel').hidden=true;$('#search-toggle').focus()};
$('#search-form').onsubmit=e=>{e.preventDefault();navigate('/search?q='+encodeURIComponent($('#search').value.trim()));};
function navigate(path){history.pushState({},'',path);render();window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!a.hash&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();navigate(a.pathname+a.search)}});window.onpopstate=render;
function card(p){const prices=p.variants.map(v=>v.price),low=Math.min(...prices);return `<article class="card"><a href="/products/${encodeURIComponent(p.handle)}"><div class="image"><img src="${esc(p.images[0]?.src||'')}" alt="${esc(p.images[0]?.alt||p.title)}" loading="lazy" width="400" height="400"></div><h2>${esc(p.title)}</h2></a><p class="price">${Math.max(...prices)!==low?'From ':''}${money(low)} EUR</p></article>`}
function catalog(search=false,all=false){let list=products.filter(p=>p.status==='active');let q=new URLSearchParams(location.search).get('q')||'';let sort=new URLSearchParams(location.search).get('sort')||'title';if(search){$('#search').value=q;list=list.filter(p=>(p.title+' '+p.description.replace(/<[^>]*>/g,' ')).toLowerCase().includes(q.toLowerCase()))}list.sort((a,b)=>sort==='price-up'?Math.min(...a.variants.map(v=>v.price))-Math.min(...b.variants.map(v=>v.price)):sort==='price-down'?Math.min(...b.variants.map(v=>v.price))-Math.min(...a.variants.map(v=>v.price)):a.title.localeCompare(b.title));
const count=list.length;if(!all&&!search)list=list.slice(0,24);document.title=search?'Search — Sudsy’s Soaps':'Sudsy’s Soaps';
$('#main').innerHTML=`${all||search?`<div class="toolbar"><h1>${search?'Search results':'All products'}</h1><label><span class="sr-only">Sort products</span><select id="sort"><option value="title">Alphabetically, A–Z</option><option value="price-up">Price, low to high</option><option value="price-down">Price, high to low</option></select></label></div>${search?`<p class="result-count">${count} ${count===1?'result':'results'} for “${esc(q)}”</p>`:''}`:''}<div class="grid">${list.map(card).join('')}</div>${!list.length?'<div class="empty"><p>No products found. Try a different search.</p><a class="button secondary" href="/collections/all">Browse all products</a></div>':''}${!all&&!search?'<div class="view-all"><a class="button secondary" href="/collections/all">View all</a></div>':''}`;
if($('#sort')){$('#sort').value=sort;$('#sort').onchange=e=>{const u=new URL(location.href);u.searchParams.set('sort',e.target.value);navigate(u.pathname+u.search)}}}
function safeDescription(raw){const t=document.createElement('template');t.innerHTML=raw;for(const el of t.content.querySelectorAll('*')){if(['SCRIPT','IFRAME','OBJECT','STYLE','LINK','FORM'].includes(el.tagName)){el.remove();continue}for(const attr of [...el.attributes]){if(attr.name.startsWith('on')||((attr.name==='href'||attr.name==='src')&&/^\s*(javascript|data):/i.test(attr.value)))el.removeAttribute(attr.name)}if(el.tagName==='IMG')el.remove()}return t.innerHTML}
function product(handle){const p=products.find(p=>p.handle===handle);if(!p){notFound();return}document.title=p.title+' — Sudsy’s Soaps';let vi=Math.max(0,p.variants.findIndex(available));$('#main').innerHTML=`<a class="back" href="/">← Back to shop</a><div class="product"><div><img id="product-photo" class="product-hero" src="${esc(p.images[0]?.src)}" alt="${esc(p.title)}"><div class="thumbs">${p.images.map((im,i)=>`<button class="${i===0?'active':''}" data-photo="${i}" aria-label="View product photo ${i+1}"><img src="${esc(im.src)}" alt="" loading="lazy"></button>`).join('')}</div></div><section><h1>${esc(p.title)}</h1><p id="product-price" class="price"></p>${p.variants.length>1?`<label for="variant">${esc(p.options.filter(Boolean).join(' / ')||'Option')}</label><select id="variant">${p.variants.map((v,i)=>`<option value="${i}">${esc(v.options.join(' / '))}${available(v)?'':' — Sold out'}</option>`).join('')}</select>`:''}<label for="quantity">Quantity</label><div class="quantity"><button id="qty-minus" aria-label="Decrease quantity">−</button><input id="quantity" type="number" value="1" min="1" max="99" inputmode="numeric"><button id="qty-plus" aria-label="Increase quantity">+</button></div><button class="button add" id="add"></button><p class="availability" id="availability"></p><div class="description">${safeDescription(p.description)}</div></section></div>`;
function update(){$('#product-price').textContent=money(p.variants[vi].price)+' EUR';$('#add').disabled=!available(p.variants[vi])||p.giftCard;$('#add').textContent=p.giftCard?'Gift cards coming soon':available(p.variants[vi])?'Add to basket':'Sold out';$('#availability').textContent=p.giftCard?'Gift-card issuing and redemption will be connected before launch.':'Preview basket only · Checkout is not yet available';$('#quantity').max=Math.max(1,cap(p.variants[vi]));$('#quantity').value=1;const img=p.variants[vi].image;if(img)$('#product-photo').src=img}
if($('#variant')){$('#variant').value=vi;$('#variant').onchange=e=>{vi=Number(e.target.value);update()}}
const qty=()=>Math.max(1,Math.min(Number($('#quantity').max),Math.floor(Number($('#quantity').value)||1)));
$('#qty-minus').onclick=()=>$('#quantity').value=Math.max(1,qty()-1);$('#qty-plus').onclick=()=>$('#quantity').value=Math.min(Number($('#quantity').max),qty()+1);$('#quantity').onchange=()=>$('#quantity').value=qty();
$('#add').onclick=()=>{const v=p.variants[vi];if(!available(v)||p.giftCard)return;const old=cart.find(x=>x.handle===p.handle&&x.variant===vi),total=(old?.qty||0)+qty();if(total>cap(v)){notify('You have reached the available stock for this option.');return}if(old)old.qty=total;else cart.push({handle:p.handle,variant:vi,qty:qty()});save();notify('Added to your basket')};
document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{const im=p.images[Number(b.dataset.photo)];$('#product-photo').src=im.src;$('#product-photo').alt=im.alt;document.querySelectorAll('[data-photo]').forEach(x=>x.classList.toggle('active',x===b))});update()}
function basket(){document.title='Your basket — Sudsy’s Soaps';if(!cart.length){$('#main').innerHTML='<div class="empty"><h1>Your basket is empty</h1><a class="button" href="/collections/all">Continue shopping</a></div>';return}let total=0;$('#main').innerHTML=`<h1 class="cart-head">Your basket</h1><a class="back" href="/">Continue shopping</a>${cart.map((line,i)=>{const p=products.find(p=>p.handle===line.handle),v=p.variants[line.variant];total+=v.price*line.qty;return `<article class="cart-row"><a href="/products/${esc(p.handle)}"><img src="${esc(v.image||p.images[0]?.src)}" alt="${esc(p.title)}"></a><div><h2><a href="/products/${esc(p.handle)}">${esc(p.title)}</a></h2>${v.options[0]!=='Default Title'?`<div>${esc(v.options.join(' / '))}</div>`:''}<div>${money(v.price)}</div><button class="remove" data-remove="${i}">Remove</button></div><div class="quantity"><button data-change="${i}" data-delta="-1" aria-label="Decrease quantity of ${esc(p.title)}">−</button><span style="width:54px;text-align:center">${line.qty}</span><button data-change="${i}" data-delta="1" aria-label="Increase quantity of ${esc(p.title)}">+</button></div><span class="line-total">${money(v.price*line.qty)}</span></article>`}).join('')}<div class="cart-total"><strong>Subtotal ${money(total)}</strong><p>Shipping and any applicable taxes will be confirmed when checkout is connected.</p><button class="button" disabled>Checkout coming soon</button><p>This preview cannot accept orders or payments.</p></div>`;
document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);save();basket()});document.querySelectorAll('[data-change]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.change),line=cart[i],p=products.find(p=>p.handle===line.handle),v=p.variants[line.variant],n=line.qty+Number(b.dataset.delta);if(n>cap(v)){notify('You have reached the available stock for this option.');return}if(n<1)cart.splice(i,1);else line.qty=n;save();basket()})}
function notFound(){$('#main').innerHTML='<div class="empty"><h1>Page not found</h1><a class="button" href="/">Return to shop</a></div>'}
function render(){const path=decodeURIComponent(location.pathname).replace(/\/$/,'')||'/';if(path==='/'||path==='/index.html')catalog();else if(path==='/collections/all')catalog(false,true);else if(path==='/search')catalog(true);else if(path==='/cart')basket();else if(path.startsWith('/products/'))product(path.slice(10));else notFound()}
fetch('/catalog.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json()}).then(data=>{products=data.products;cart=cart.filter(line=>typeof line.handle==='string'&&Number.isInteger(line.variant)&&Number.isInteger(line.qty)&&line.qty>0&&products.some(p=>p.handle===line.handle&&p.variants[line.variant]));save();render()}).catch(()=>{$('#main').innerHTML='<div class="empty"><h1>The shop could not load</h1><p>Please refresh the page to try again.</p></div>'});
